input.command:
cd /workspace
timeout 120 duckdb -init init.sql -c "
CREATE OR REPLACE TABLE scope AS
 SELECT * FROM (VALUES
 (15,'Pasture','cattle',true,'pasture is a land-cover proxy for cattle, not direct production evidence'),
 (21,'Mosaic of Uses','',false,'heterogeneous mosaic of agriculture and pasture; no single Annex I commodity'),
 (39,'Soybean','soy',true,''),
 (41,'Other Temporary Crops','',false,'heterogeneous temporary-crop class; may include non-Annex-I crops')
 ) t(mbmode24, mb_class, annex1_commodity, in_scope, caveat);
CREATE OR REPLACE TABLE mf AS
 SELECT m.*, s.annex1_commodity, s.in_scope, s.mb_class
 FROM 'matched_fields.parquet' m JOIN scope s ON CAST(m.mbmode24 AS INT)=s.mbmode24;
COPY (SELECT mbmode24, mb_class, annex1_commodity, in_scope, caveat FROM scope ORDER BY mbmode24) TO '/tmp/q16.csv' (HEADER, FORMAT CSV);
COPY (SELECT annex1_commodity, count(*) AS n_fields, round(sum(d2124)/10000.0,6) AS post2020_loss_ha
      FROM mf WHERE in_scope GROUP BY annex1_commodity ORDER BY post2020_loss_ha DESC) TO '/tmp/q17.csv' (HEADER, FORMAT CSV);
COPY (SELECT mb_class, count(*) AS n_fields, round(sum(d2124)/10000.0,6) AS post2020_loss_ha
      FROM mf WHERE NOT in_scope GROUP BY mb_class ORDER BY post2020_loss_ha DESC) TO '/tmp/q18.csv' (HEADER, FORMAT CSV);
COPY (SELECT annex1_commodity, round(sum(field_m2)/10000.0,6) AS total_ha,
             round(sum(d2124)/sum(field_m2),6) AS loss_share
      FROM mf WHERE in_scope GROUP BY annex1_commodity ORDER BY total_ha DESC) TO '/tmp/q19.csv' (HEADER, FORMAT CSV);
COPY (SELECT best_cod AS cod_imovel, best_municipio AS municipio,
             round(sum(d2124)/10000.0,6) AS post2020_loss_ha,
             count(*) FILTER (WHERE d2124>0) AS n_fields_post2020_loss
      FROM mf WHERE in_scope GROUP BY best_cod, best_municipio
      ORDER BY post2020_loss_ha DESC, cod_imovel ASC LIMIT 10) TO '/tmp/q20.csv' (HEADER, FORMAT CSV);
COPY (SELECT Id AS field_id, best_cod AS cod_imovel, annex1_commodity,
             round(field_m2/10000.0,6) AS field_area_ha, round(d2124/10000.0,6) AS post2020_loss_ha
      FROM mf WHERE in_scope ORDER BY d2124 DESC, field_id ASC LIMIT 10) TO '/tmp/q23.csv' (HEADER, FORMAT CSV);
" 2>&1 | grep -v "Loading resources"
for q in q16 q17 q18 q19 q20 q23; do echo "=== $q ==="; cat /tmp/$q.csv; done

